import json

def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    output = [[0] * cols for _ in range(rows)]
    floor_val = 0
    floor_row = None

    for i in range(rows):
        row = grid[i]
        if all(v == row[0] for v in row) and row[0] != 0:
            floor_val = row[0]
            floor_row = i
            break

    if floor_row is not None:
        for c in range(cols):
            output[floor_row][c] = floor_val
    else:
        for j in range(cols):
            col_vals = [grid[i][j] for i in range(rows)]
            if all(v == col_vals[0] for v in col_vals) and col_vals[0] != 0:
                floor_val = col_vals[0]
                for r in range(rows):
                    output[r][j] = floor_val
                break

    for c in range(cols):
        vals = []
        for r in range(rows):
            if r != floor_row and grid[r][c] != 0:
                vals.append(grid[r][c])
        n = len(vals)
        if n == 0:
            pass
        elif n == 1:
            if vals[0] == vals[0]:  # check if same
                output[8][c] = vals[0]
            else:
                output[6][c] = vals[0]
        elif n == 2:
            output[6][c] = vals[0]
            output[8][c] = vals[1]
        else:
            output[6][c] = vals[0]
            output[7][c] = vals[1]
            output[8][c] = vals[2]

    return output

